// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 tokenId) public {
        // Ensure tokenId is valid by creating a game item (admin only)
        vm.assume(tokenId < 10);
        // Create a game item with some arbitrary parameters (only needed once, but we do it per fuzz)
        // Actually we need to ensure the item exists. We'll create a dummy item if needed.
        // But to keep it simple, we assume tokenId is within the range of created items.
        // In setUp we could create items, but for generality we do it here.
        // However, creating items modifies state, so we need to be careful.
        // Instead, we avoid needing an item: balanceOf works for any id, even if no item exists.
        // So we just call balanceOf directly.
        // The rule: balanceOf returns 0 for zero address, else something.
        // But we need to compare P and M: P reverts for zero address, M returns 0.
        // So the general rule is: P reverts for zero address, M does not.
        // Since we cannot call P directly, we test the behavior of the deployed C.
        // The test must pass for P (reference) and fail for M (buggy).
        // For P, calling balanceOf(zero address, any) reverts.
        // For M, it returns 0.
        // So we assert that calling balanceOf(zero address, any) does NOT revert (i.e., returns a value).
        // This will pass for M (buggy) but fail for P, so we need to invert.
        // Actually the instruction: test PASSES on reference and FAILS on version with bug.
        // So we need an assertion that is true for P and false for M.
        // For P: balanceOf(0, id) reverts.
        // For M: balanceOf(0, id) returns 0.
        // So the rule could be: balanceOf(0, id) reverts.
        // But we cannot bypass revert. We can use try/catch.
        bool reverted;
        try c.balanceOf(address(0), tokenId) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

